#![forbid(unsafe_code)]
use sv_claude_kaggle::{self as sv,need,parse,sha,R};
use std::{fs,path::Path,io::Write};use serde_json::json;
fn run()->R<()>{let a=std::env::args().collect::<Vec<_>>();need(a.len()==5,"Uso: recibir-adjudicacion CLAVE JUICIO CORTE SALIDA")?;let kbytes=fs::read(&a[1]).map_err(|e|e.to_string())?;let k=parse(&kbytes)?;let jbytes=fs::read(&a[2]).map_err(|e|e.to_string())?;let j=parse(&jbytes)?;need(j["clave_sha256"]==sha(&kbytes)&&j["autoridad"]=="dictamen asistido exterior al candidato"&&j["recepcion_independiente"]=="pendiente","Identidad de adjudicación")?;
 let rows=j["adjudicaciones"].as_array().ok_or("Juicios ausentes")?;need(rows.len()==27,"Cobertura incompleta")?;let mut stages=vec![];
 for stage in 0..3{let mut correct=0;let mut critical_ok=true;let mut ids=std::collections::BTreeSet::new();for r in rows.iter().filter(|v|v["etapa"]==stage){let id=r["caso"].as_str().ok_or("Caso")?;need(ids.insert(id),"Caso duplicado")?;let key=k["preguntas"].as_array().ok_or("Clave")?.iter().find(|v|v["id"]==id).ok_or("Caso fuera de clave")?;need(r["critica"]==key["critica"]&&r["criterio"]==key["criterio"]&&r["motivo"].as_str().is_some_and(|v|!v.is_empty()),"Criterio cambiado o motivo ausente")?;
 let text=fs::read(Path::new(&a[3]).join(format!("manual/{id}-R{stage}/FINAL.txt"))).map_err(|e|e.to_string())?;need(r["final_sha256"]==sha(&text),"Juicio de respuesta diferente")?;let mark=r["valor"].as_str().ok_or("Valor")?;need(["0","1","U"].contains(&mark),"Valor fuera de escala")?;if mark=="0"{correct+=1;}else if key["critica"]==true{critical_ok=false;}}
 need(ids.len()==9,"Etapa incompleta")?;stages.push(json!({"etapa":stage,"correctas":correct,"total":9,"criticos_correctos":critical_ok,"umbral":k["umbral_correctas"],"admisible_segun_clave":correct>=k["umbral_correctas"].as_u64().ok_or("Umbral")?&&critical_ok}));}
 let report=json!({"conforme":true,"alcance":"Cotejo de identidad, cobertura y cálculo; no sustituye el juicio semántico asistido ni la recepción independiente","juicio_sha256":sha(&jbytes),"clave_sha256":sha(&kbytes),"resultados":stages,"etapa_final":2,"mejor_etapa_seleccionada":false,"recepcion_independiente":"pendiente","licencia":sv::LICENCIA});let mut f=fs::OpenOptions::new().create_new(true).write(true).open(&a[4]).map_err(|e|e.to_string())?;f.write_all(&serde_json::to_vec_pretty(&report).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;println!("Adjudicación recibida: 27 juicios; tres etapas calculadas; recepción independiente pendiente");Ok(())}
fn main(){if let Err(e)=run(){eprintln!("NO CONFORME: {e}");std::process::exit(1)}}
